def findseq(seq, n, allowwrap=True):
    for s in range(n) if allowwrap else []:
        t=[(seq[i+s%n] if allowwrap or True else seq[(i+s)%n]) for i in range(n)]
        if t==seq: yield s
    # search positions directly
    for si in range(n):
        ok=True
        for i,c in enumerate(seq):
            if (allowwrap and c!=seq[(si+i)%n]) or (not allowwrap and c!=seq[si+i]): ok=False;break
        if ok: yield si
